"use client";

import { ArrowLeft, ArrowRight, Check, ChevronDown, CircleAlert, CircleCheck, CloudLightning, Database, Gift, KeyRound, Layers3, Loader2, Orbit, PlugZap, RefreshCw, Search, ShieldCheck, Timer, UserRound, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";

type Choice = { id: string; name: string; currency?: string; status?: string; type?: string; selected?: boolean };
type Overview = { connected: boolean; authorizedAt?: string; businessCenters: Choice[]; advertisers: Choice[]; warnings: string[] };
type Detail = { advertiser: Choice | null; pixels: Choice[]; identities: Choice[]; warnings: string[] };
type Notice = { tone: "success" | "warning" | "error"; text: string };
type CatalogMode = "ALL" | "SETS";
type OperatingSystem = "ALL" | "ANDROID" | "IOS";

const currencies = ["BRL", "USD", "MXN", "CLP", "COP", "PEN", "ARS"];
const steps = ["CONECTAR", "CONTAS", "CATÁLOGO", "CRIATIVOS", "ESTRUTURA", "PROXY", "LANÇAR"] as const;
const navAssets = ["connect", "accounts", "catalog", "creative", "structure", "proxy", "launch"] as const;
const stageCopy = [["Forjando nova rota.", "Autorize o canal para montar sua operação."], ["Contas de anúncio", "Selecione as contas que deseja gerenciar."], ["Catálogo", "Selecione um catálogo por Business Center."], ["Adicionar criativos", "Configure vídeo, texto do anúncio, CTA e complementos interativos."], ["Estrutura ABO", "Defina volume, orçamento, público e nomenclatura."], ["Rota de saída", "Defina o caminho de rede da operação."], ["Preparar lançamento", "Revise cada ativo antes de enviar ao TikTok."]] as const;

function money(value: number, currency: string) { return new Intl.NumberFormat("pt-BR", { style: "currency", currency, maximumFractionDigits: 2 }).format(value); }
function dateLabel(value?: string) { const date = value ? new Date(value) : null; return date && !Number.isNaN(date.getTime()) ? date.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" }) : "agora"; }

export default function Home() {
  const router = useRouter(); const [step, setStep] = useState(0);
  const [overview, setOverview] = useState<Overview>({ connected: false, businessCenters: [], advertisers: [], warnings: [] });
  const [details, setDetails] = useState<Detail>({ advertiser: null, pixels: [], identities: [], warnings: [] }); const [catalogs, setCatalogs] = useState<Choice[]>([]);
  const [bcId, setBcId] = useState(""); const [advertiserId, setAdvertiserId] = useState(""); const [catalogId, setCatalogId] = useState(""); const [pixelId, setPixelId] = useState(""); const [identityId, setIdentityId] = useState("");
  const [query, setQuery] = useState(""); const [activeOnly, setActiveOnly] = useState(false); const [catalogMode, setCatalogMode] = useState<CatalogMode>("ALL"); const [adText, setAdText] = useState(""); const [pullCatalogText, setPullCatalogText] = useState(false); const [cta, setCta] = useState("LEARN_MORE"); const [addon, setAddon] = useState("NONE"); const [proxy, setProxy] = useState("DIRECT"); const [proxyAddress, setProxyAddress] = useState("");
  const [campaignName, setCampaignName] = useState(""); const [inputCurrency, setInputCurrency] = useState("MXN"); const [amount, setAmount] = useState("20000"); const [rate, setRate] = useState("0.30"); const [campaigns, setCampaigns] = useState("1"); const [groups, setGroups] = useState("1"); const [ads, setAds] = useState("1"); const [country, setCountry] = useState("MX"); const [language, setLanguage] = useState("es");
  const [aigc, setAigc] = useState(false); const [cpa, setCpa] = useState(false); const [clickWindow, setClickWindow] = useState("7-day click"); const [viewWindow, setViewWindow] = useState("1-day view"); const [counting, setCounting] = useState("Every"); const [ages, setAges] = useState(["18–24", "25–34", "35–44", "45–54", "55+"]); const [operatingSystem, setOperatingSystem] = useState<OperatingSystem>("ALL"); const [showRegions, setShowRegions] = useState(false); const [regions, setRegions] = useState<string[]>([]);
  const [loading, setLoading] = useState<"overview" | "assets" | "catalogs" | null>(null); const [notice, setNotice] = useState<Notice | null>(null); const [showConsole, setShowConsole] = useState(false);
  const connectedBusinessCenters = overview.businessCenters.filter((item) => item.selected); const selectedBc = connectedBusinessCenters.find((item) => item.id === bcId) ?? null; const selectedAdvertiser = overview.advertisers.find((item) => item.id === advertiserId) ?? details.advertiser; const selectedCatalog = catalogs.find((item) => item.id === catalogId) ?? null; const selectedPixel = details.pixels.find((item) => item.id === pixelId) ?? null; const selectedIdentity = details.identities.find((item) => item.id === identityId) ?? null; const accountCurrency = details.advertiser?.currency ?? selectedAdvertiser?.currency ?? "BRL";
  const counts = useMemo(() => { const campaignCount = Math.max(1, Number(campaigns) || 1); const groupCount = campaignCount * Math.max(1, Number(groups) || 1); return { campaigns: campaignCount, groups: groupCount, ads: groupCount * Math.max(1, Number(ads) || 1) }; }, [ads, campaigns, groups]);
  const budget = useMemo(() => { const value = Number(amount.replace(",", ".")) || 0; const fx = inputCurrency === accountCurrency ? 1 : Number(rate.replace(",", ".")) || 0; return value * fx; }, [accountCurrency, amount, inputCurrency, rate]);
  const ready = Boolean(bcId && advertiserId && catalogId && pixelId && identityId && (pullCatalogText || adText.trim()) && campaignName.trim() && (proxy !== "DEDICATED" || proxyAddress.trim())); const warnings = overview.warnings.concat(details.warnings); const filteredAdvertisers = overview.advertisers.filter((item) => (item.name + " " + item.id).toLowerCase().includes(query.toLowerCase())).filter((item) => !activeOnly || !item.status || /active|enable|normal/i.test(item.status));
  const loadOverview = useCallback(async () => { setLoading("overview"); try { const response = await fetch("/api/tiktok/assets?scope=overview", { cache: "no-store" }); const payload = await response.json() as Overview & { error?: string }; if (!response.ok) throw new Error(payload.error || "Não foi possível consultar o TikTok."); setOverview(payload); if (!payload.connected) setNotice({ tone: "warning", text: "Conecte o TikTok para carregar ativos reais desta sessão." }); else { const firstSelected = payload.businessCenters.find((item) => item.selected)?.id ?? ""; setBcId((current) => payload.businessCenters.some((item) => item.id === current && item.selected) ? current : firstSelected); setCatalogId(""); setAdvertiserId((current) => current || payload.advertisers[0]?.id || ""); setNotice({ tone: "success", text: payload.businessCenters.filter((item) => item.selected).length + " Business Center(s) conectado(s) de " + payload.businessCenters.length + " disponível(is); " + payload.advertisers.length + " conta(s) carregadas." }); } } catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "Falha ao carregar os ativos." }); } finally { setLoading(null); } }, []);
  const toggleBusinessCenter = useCallback(async (id: string, selected: boolean) => { setLoading("overview"); try { const response = await fetch("/api/tiktok/assets", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ bc_id: id, selected }) }); const payload = await response.json() as { businessCenters?: Choice[]; error?: string }; if (!response.ok || !payload.businessCenters) throw new Error(payload.error || "Não foi possível atualizar a Business Center."); setOverview((current) => ({ ...current, businessCenters: payload.businessCenters ?? current.businessCenters })); const nextSelected = payload.businessCenters.filter((item) => item.selected); if (selected) { setBcId(id); setCatalogId(""); } else if (bcId === id) { setBcId(nextSelected[0]?.id ?? ""); setCatalogId(""); } setNotice({ tone: "success", text: selected ? "Business Center conectada à operação." : "Business Center removida da operação." }); } catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "Falha ao atualizar a Business Center." }); await loadOverview(); } finally { setLoading(null); } }, [bcId, loadOverview]);
  const loadAssets = useCallback(async (id: string) => { if (!id || !overview.connected) return; setLoading("assets"); try { const response = await fetch(`/api/tiktok/assets?scope=advertiser&advertiser_id=${encodeURIComponent(id)}`, { cache: "no-store" }); const payload = await response.json() as Detail & { error?: string }; if (!response.ok) throw new Error(payload.error || "Não foi possível carregar os ativos da conta."); setDetails(payload); setPixelId((current) => current || payload.pixels[0]?.id || ""); setIdentityId((current) => current || payload.identities[0]?.id || ""); } catch (error) { setDetails({ advertiser: null, pixels: [], identities: [], warnings: [error instanceof Error ? error.message : "Falha ao carregar os ativos."] }); } finally { setLoading(null); } }, [overview.connected]);
  const loadCatalogs = useCallback(async (id: string) => { if (!id || !overview.connected) return; setLoading("catalogs"); try { const response = await fetch(`/api/tiktok/assets?scope=catalogs&bc_id=${encodeURIComponent(id)}`, { cache: "no-store" }); const payload = await response.json() as { catalogs?: Choice[]; error?: string }; if (!response.ok) throw new Error(payload.error || "Não foi possível carregar os catálogos."); const list = payload.catalogs ?? []; setCatalogs(list); setCatalogId((current) => current || list[0]?.id || ""); } catch (error) { setCatalogs([]); setNotice({ tone: "warning", text: error instanceof Error ? error.message : "O TikTok não retornou catálogos." }); } finally { setLoading(null); } }, [overview.connected]);
  useEffect(() => { if (new URLSearchParams(window.location.search).get("tiktok") === "connected") window.history.replaceState({}, "", window.location.pathname); const timer = window.setTimeout(() => void loadOverview(), 0); return () => window.clearTimeout(timer); }, [loadOverview]);
  useEffect(() => { if (!advertiserId) return; const timer = window.setTimeout(() => void loadAssets(advertiserId), 0); return () => window.clearTimeout(timer); }, [advertiserId, loadAssets]);
  useEffect(() => { if (!bcId) return; const timer = window.setTimeout(() => void loadCatalogs(bcId), 0); return () => window.clearTimeout(timer); }, [bcId, loadCatalogs]);
  const go = (next: number) => { setStep(next); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const applyPreset = () => { setCampaigns("1"); setGroups("3"); setAds("1"); setInputCurrency("MXN"); setAmount("20000"); setCountry("MX"); setLanguage("es"); setCta("LEARN_MORE"); setAddon("NONE"); setAigc(false); setCpa(false); setAges(["18–24", "25–34", "35–44", "45–54", "55+"]); setOperatingSystem("ALL"); setNotice({ tone: "success", text: "Preset ABO México aplicado à configuração atual." }); };
  const disabled = step === 6 ? !ready : false;
  return <main className="rocket-layout min-h-screen overflow-x-hidden bg-[#0b0f13] text-zinc-100 selection:bg-[#d8b56b] selection:text-black"><div aria-hidden className="thor-storm fixed inset-0" /><div aria-hidden className="thor-scanlines pointer-events-none fixed inset-0" /><RocketHeader connected={overview.connected} bcs={connectedBusinessCenters.length} loading={loading === "overview"} onRefresh={loadOverview} onPreset={applyPreset} /><div className="relative mx-auto flex min-h-[calc(100vh-60px)] max-w-[1720px] flex-col px-6 pb-5 pt-3 lg:px-10"><Journey step={step} onChange={go} />{notice && <NoticeBanner notice={notice} onClose={() => setNotice(null)} />}{warnings.length > 0 && <Warnings items={warnings} />}<section className="flex-1 pt-2"><StageTitle title={stageCopy[step][0]} subtitle={stageCopy[step][1]} />{step === 0 && <ConnectScreen connected={overview.connected} date={overview.authorizedAt} bcs={connectedBusinessCenters.length} advertisers={overview.advertisers.length} businessCenters={overview.businessCenters} selectedBcId={bcId} loading={loading === "overview"} onConnect={() => router.push("/api/tiktok/connect")} onRefresh={loadOverview} onSelectBc={(id) => { setBcId(id); setCatalogId(""); }} onToggleBusinessCenter={toggleBusinessCenter} onManageCatalogs={() => go(2)} />}{step === 1 && <AccountsScreen advertisers={filteredAdvertisers} query={query} setQuery={setQuery} activeOnly={activeOnly} onToggleFilter={() => setActiveOnly((value) => !value)} advertiserId={advertiserId} pixelId={pixelId} identityId={identityId} pixels={details.pixels} identities={details.identities} loading={loading === "assets"} onAdvertiser={(id) => { setAdvertiserId(id); setPixelId(""); setIdentityId(""); }} onPixel={setPixelId} onIdentity={setIdentityId} />}{step === 2 && <CatalogScreen bc={selectedBc} bcs={connectedBusinessCenters} catalogs={catalogs} selectedId={catalogId} mode={catalogMode} loading={loading === "catalogs"} onBc={(id) => { setBcId(id); setCatalogId(""); }} onRefresh={() => void loadCatalogs(bcId)} onSelect={setCatalogId} onMode={setCatalogMode} />}{step === 3 && <CreativeScreen value={adText} pullCatalogText={pullCatalogText} cta={cta} addon={addon} onChange={setAdText} onPullCatalogText={setPullCatalogText} onCta={setCta} onAddon={setAddon} />}{step === 4 && <StructureScreen campaigns={campaigns} groups={groups} ads={ads} setCampaigns={setCampaigns} setGroups={setGroups} setAds={setAds} inputCurrency={inputCurrency} setInputCurrency={setInputCurrency} amount={amount} setAmount={setAmount} rate={rate} setRate={setRate} accountCurrency={accountCurrency} budget={budget} counts={counts} country={country} setCountry={setCountry} language={language} setLanguage={setLanguage} campaignName={campaignName} setCampaignName={setCampaignName} aigc={aigc} onAigc={setAigc} cpa={cpa} onCpa={setCpa} clickWindow={clickWindow} onClickWindow={setClickWindow} viewWindow={viewWindow} onViewWindow={setViewWindow} counting={counting} onCounting={setCounting} ages={ages} onAges={setAges} operatingSystem={operatingSystem} onOperatingSystem={setOperatingSystem} showRegions={showRegions} onShowRegions={() => setShowRegions((value) => !value)} regions={regions} onRegions={setRegions} />}{step === 5 && <ProxyScreen proxy={proxy} address={proxyAddress} onChange={setProxy} onAddress={setProxyAddress} />}{step === 6 && <LaunchScreen ready={ready} name={campaignName} bc={selectedBc} advertiser={selectedAdvertiser} catalog={selectedCatalog} pixel={selectedPixel} identity={selectedIdentity} counts={counts} budget={budget} currency={accountCurrency} onOpen={() => setShowConsole(true)} />}</section><FooterNav step={step} onBack={() => go(Math.max(0, step - 1))} onNext={() => step === 6 ? setShowConsole(true) : go(step + 1)} disabled={disabled} /></div>{showConsole && <LaunchConsole name={campaignName} counts={counts} budget={budget} currency={accountCurrency} ready={ready} onClose={() => setShowConsole(false)} />}</main>;
}

function RocketHeader({ connected, bcs, loading, onRefresh, onPreset }: { connected: boolean; bcs: number; loading: boolean; onRefresh: () => void; onPreset: () => void }) { return <header className="relative z-20 h-[60px] border-b border-white/[.055] bg-[#070a0c]/90"><div className="mx-auto flex h-full max-w-[1720px] items-center justify-between px-6 lg:px-10"><div><p className="thor-title text-[22px] leading-5 text-white">Thor<span className="text-[#d8b56b]">Tk</span></p><p className="mt-1 text-[9px] font-black uppercase tracking-[.2em] text-[#8ca6c7]">Criar campanhas</p></div><div className="flex items-center gap-2"><HeaderChip tone="blue" text={`BCs ${bcs}`} /><HeaderChip tone="red" text="GASTO HOJE 0,00" /><HeaderChip tone="green" text="SALDO --" /><button type="button" onClick={onPreset} className="header-chip hidden md:flex" title="Aplicar preset ABO México"><KeyRound size={13} />PRESETS</button><button type="button" onClick={onRefresh} className="header-chip text-[#d8b56b]" title="Atualizar ativos"><RefreshCw size={14} className={loading ? "animate-spin" : ""} />{connected ? "CANAL ATIVO" : "CONECTAR"}</button></div></div></header>; }
function HeaderChip({ tone, text }: { tone: "blue" | "red" | "green"; text: string }) { const color = tone === "blue" ? "border-sky-400/30 text-sky-300" : tone === "red" ? "border-red-400/25 text-red-300" : "border-emerald-400/25 text-emerald-300"; return <span className={`header-chip hidden sm:flex ${color}`}>{text}</span>; }
function Journey({ step, onChange }: { step: number; onChange: (step: number) => void }) { return <nav aria-label="Etapas do lançamento" className="relative -mx-2 overflow-x-auto pb-3 pt-4 [scrollbar-width:none]"><div className="relative flex min-w-[980px] items-start justify-between px-4"><div aria-hidden className="absolute left-[7%] right-[7%] top-8 border-t border-dashed border-[#4c5459]/55" />{steps.map((label, index) => { const active = index === step; return <button key={label} type="button" onClick={() => onChange(index)} className="relative z-10 flex w-[118px] flex-col items-center gap-2.5"><span className={`journey-icon ${active ? "journey-active" : ""}`}><Image src={`/thor-icon-${navAssets[index]}.png`} alt="" width={56} height={56} priority={index < 2} /></span><span className={`text-[10px] font-black tracking-[.07em] ${active ? "text-[#86c7ff]" : "text-zinc-500"}`}>{label}</span></button>; })}</div></nav>; }
function StageTitle({ title, subtitle }: { title: string; subtitle: string }) { return <div className="pt-1"><h1 className="thor-title thor-title--storm text-[26px] leading-tight">{title}</h1><p className="mt-1 text-sm text-zinc-400">{subtitle}</p></div>; }
function NoticeBanner({ notice, onClose }: { notice: Notice; onClose: () => void }) { const style = notice.tone === "success" ? "border-emerald-400/25 bg-emerald-400/[.07] text-emerald-100" : notice.tone === "error" ? "border-red-400/25 bg-red-400/[.08] text-red-100" : "border-amber-400/25 bg-amber-400/[.08] text-amber-100"; return <div className={`mt-3 flex items-center justify-between gap-4 rounded-lg border px-4 py-3 text-xs ${style}`}><span className="flex items-center gap-2">{notice.tone === "success" ? <CircleCheck size={15} /> : <CircleAlert size={15} />}{notice.text}</span><button type="button" onClick={onClose}><X size={15} /></button></div>; }
function Warnings({ items }: { items: string[] }) { return <div className="mt-3 rounded-lg border border-amber-400/20 bg-[#211d0b]/65 px-4 py-3 text-xs text-amber-100"><p className="font-black uppercase tracking-[.12em]">Retorno parcial do TikTok</p><ul className="mt-2 list-disc space-y-1 pl-4">{items.map((item, index) => <li key={`${item}-${index}`}>{item}</li>)}</ul></div>; }

function ConnectScreen({ connected, date, bcs, advertisers, businessCenters, selectedBcId, loading, onConnect, onRefresh, onSelectBc, onToggleBusinessCenter, onManageCatalogs }: { connected: boolean; date?: string; bcs: number; advertisers: number; businessCenters: Choice[]; selectedBcId: string; loading: boolean; onConnect: () => void; onRefresh: () => void; onSelectBc: (id: string) => void; onToggleBusinessCenter: (id: string, selected: boolean) => void; onManageCatalogs: () => void }) {
  return <div className="mx-auto max-w-[650px] pt-7 text-center"><div className="thor-crest"><Image src="/thor-connect-central.png" alt="Símbolo de conexão do Thor" width={88} height={88} priority /></div><h2 className="thor-title thor-title--storm mt-4 text-[30px] leading-tight">{connected ? "Força Pronta" : "Canal Inativo"}</h2><p className="mx-auto mt-3 max-w-lg text-sm leading-6 text-zinc-400">{connected ? `${bcs} Business Center(s) conectada(s) de ${businessCenters.length} disponível(is) · ${advertisers} conta(s) carregadas.` : "Autorize o TikTok para carregar seus ativos reais e preparar a estrutura ABO."}</p><div className="mt-7 space-y-3 text-left"><div className="rocket-card border-[#d8b56b]/35 bg-[#17150e]/80 p-5"><div className="flex items-center gap-4"><span className="grid h-12 w-12 place-items-center overflow-hidden rounded-full bg-[#121519] shadow-[0_0_20px_rgba(216,181,107,.2)]"><Image src="/thor-command.png" alt="Comando de Thor" width={48} height={48} /></span><div><div className="flex items-center gap-2"><p className="font-black">Comando de Thor</p><span className="rounded bg-[#403516] px-2 py-0.5 text-[9px] font-black uppercase tracking-wide text-[#e3c985]">modo ABO</span></div><p className="mt-1 text-xs leading-5 text-zinc-400">Conecte somente as Business Centers que farão parte desta operação.</p></div></div></div>{connected ? <><div className="rocket-card border-emerald-400/35 bg-emerald-400/[.07] px-5 py-4"><div className="flex items-center gap-3"><span className="h-2 w-2 rounded-full bg-emerald-400 shadow-[0_0_13px_#34d399]" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-black text-zinc-100">Canal TikTok autorizado</p><p className="mt-1 text-[11px] text-zinc-500">Última autorização: {dateLabel(date)}</p></div><button type="button" onClick={onRefresh} disabled={loading} aria-label="Atualizar Business Centers" className="text-sky-300 hover:text-sky-200"><RefreshCw size={17} className={loading ? "animate-spin" : ""} /></button></div></div><div className="rocket-card p-5"><div className="flex items-center justify-between gap-3"><div><p className="section-label text-[#e3c985]">Gerenciar Business Centers</p><p className="mt-1 text-xs text-zinc-500">Conecte ou remova BCs desta operação. A remoção só vale no ThorTk e não altera a permissão no TikTok.</p></div><span className="rounded bg-[#142231] px-2 py-1 text-[10px] font-black text-sky-200">{bcs}/{businessCenters.length}</span></div>{businessCenters.length > 0 ? <div className="mt-4 grid gap-2">{businessCenters.map((center) => <div key={center.id} className={`flex items-center gap-3 rounded-lg border p-3 transition ${center.selected ? "border-[#d8b56b] bg-[#2b250e]" : "border-white/[.09] bg-[#0d1013]"}`}><button type="button" disabled={!center.selected} onClick={() => onSelectBc(center.id)} className="min-w-0 flex-1 text-left disabled:cursor-not-allowed disabled:opacity-70"><b className="block truncate text-sm text-zinc-100">{center.name}</b><small className="mt-1 block truncate text-[10px] text-zinc-500">BC ID: {center.id}</small></button><span className={`rounded px-2 py-1 text-[9px] font-black uppercase ${center.selected ? "bg-[#403516] text-[#e3c985]" : "bg-white/[.06] text-zinc-400"}`}>{center.selected ? "Conectada" : "Disponível"}</span><button type="button" disabled={loading} onClick={() => onToggleBusinessCenter(center.id, !center.selected)} className={`rounded-md border px-3 py-2 text-[10px] font-black transition ${center.selected ? "border-red-400/35 text-red-300 hover:bg-red-400/[.08]" : "border-sky-300/35 text-sky-200 hover:bg-sky-300/[.08]"}`}>{center.selected ? "Remover" : "Conectar"}</button></div>)}</div> : <div className="mt-4 rounded-lg border border-amber-300/20 bg-amber-300/[.05] px-4 py-3 text-xs leading-5 text-amber-100">Nenhuma Business Center foi retornada. O ThorTk também consulta a BC proprietária de cada conta de anúncio; atualize para tentar novamente.</div>}<button type="button" onClick={onManageCatalogs} disabled={!selectedBcId} className="rocket-outline-action mt-4 w-full disabled:cursor-not-allowed disabled:opacity-40"><Database size={17} />Gerenciar catálogos da BC selecionada<ArrowRight size={16} className="ml-auto" /></button></div></> : <button type="button" onClick={onConnect} className="rocket-outline-action"><PlugZap size={17} />Conectar TikTok Business</button>}<div className="rocket-outline-action cursor-default text-sky-300"><ShieldCheck size={17} />Tokens protegidos no servidor</div></div></div>;
}

function AccountsScreen({ advertisers, query, setQuery, activeOnly, onToggleFilter, advertiserId, pixelId, identityId, pixels, identities, loading, onAdvertiser, onPixel, onIdentity }: { advertisers: Choice[]; query: string; setQuery: (v: string) => void; activeOnly: boolean; onToggleFilter: () => void; advertiserId: string; pixelId: string; identityId: string; pixels: Choice[]; identities: Choice[]; loading: boolean; onAdvertiser: (v: string) => void; onPixel: (v: string) => void; onIdentity: (v: string) => void }) { return <div className="pt-5"><div className="flex gap-3"><label className="relative flex-1"><Search className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500" size={18} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por nome, ID ou status..." className="rocket-input pl-11" /></label><button type="button" onClick={onToggleFilter} aria-pressed={activeOnly} className={`rocket-dark-button ${activeOnly ? "border-sky-300/60 text-sky-200" : ""}`}><Layers3 size={16} />{activeOnly ? "Ativas" : "Filtro"}</button></div><div className="mt-3 overflow-hidden rounded-lg border border-white/[.075] bg-[#121719]/95"><div className="grid grid-cols-[minmax(380px,1fr)_minmax(180px,.5fr)_160px] gap-4 bg-[#1d222b] px-4 py-3 text-[11px] font-black text-zinc-400"><span>Nome da Conta</span><span>ID Externo</span><span>Status</span></div><div className="max-h-[285px] overflow-y-auto">{advertisers.length ? advertisers.map((item) => <button key={item.id} type="button" onClick={() => onAdvertiser(item.id)} className={`grid w-full grid-cols-[minmax(380px,1fr)_minmax(180px,.5fr)_160px] items-center gap-4 border-t border-white/[.06] px-4 py-3 text-left text-xs transition ${item.id === advertiserId ? "bg-[#1b2b38]/65" : "hover:bg-white/[.03]"}`}><span className="flex items-center gap-3"><span className={`grid h-4 w-4 place-items-center rounded border ${item.id === advertiserId ? "border-[#d8b56b] bg-[#d8b56b] text-black" : "border-zinc-600"}`}>{item.id === advertiserId && <Check size={12} strokeWidth={3} />}</span><span className="truncate font-bold text-zinc-100">{item.name}</span></span><span className="truncate text-sky-300">{item.id}</span><span><b className="rounded border border-emerald-400/20 bg-emerald-400/[.1] px-2 py-1 text-[10px] text-emerald-300">● Ativa</b></span></button>) : <div className="p-10 text-center text-sm text-zinc-500">Nenhuma conta foi retornada com esse filtro.</div>}</div><div className="flex items-center justify-between bg-[#1d222b] px-4 py-3 text-xs"><b className="text-[#d8b56b]">{advertiserId ? "1 CONTA SELECIONADA" : "0 CONTAS SELECIONADAS"}</b><button type="button" onClick={() => onAdvertiser("")} className="text-zinc-100 hover:text-white">Cancelar seleção</button></div></div><div className="mt-7 grid gap-6 lg:grid-cols-2"><AssetAction icon={<UserRound size={22} />} title="Identity do anúncio" description="Selecione a identidade já autorizada para esta conta."><AssetSelect label="Identidade do anúncio" values={identities} selected={identityId} loading={loading} onChange={onIdentity} empty="Selecione uma conta para carregar identidades." /></AssetAction><AssetAction icon={<Orbit size={22} />} title="Pixel de conversão" description="Selecione o pixel autorizado para registrar conversões."><AssetSelect label="Pixel de conversão" values={pixels} selected={pixelId} loading={loading} onChange={onPixel} empty="Selecione uma conta para carregar pixels." /></AssetAction></div></div>; }
function AssetAction({ icon, title, description, children }: { icon: React.ReactNode; title: string; description: string; children: React.ReactNode }) { return <div className="rocket-card min-h-[170px] p-5"><div className="flex items-center gap-4"><span className="grid h-12 w-12 place-items-center rounded-xl bg-[#2b2616] text-[#ffd31a]">{icon}</span><div><h2 className="text-xl font-black tracking-[-.04em]">{title}</h2><p className="mt-1 text-sm text-zinc-400">{description}</p></div></div><div className="mt-5">{children}</div></div>; }
function AssetSelect({ label, values, selected, loading, onChange, empty }: { label: string; values: Choice[]; selected: string; loading: boolean; onChange: (v: string) => void; empty: string }) { return <label className="block text-[10px] font-black uppercase tracking-[.1em] text-zinc-500">{label}{loading ? <span className="mt-2 flex items-center gap-2 text-xs normal-case text-zinc-400"><Loader2 className="animate-spin" size={14} />Consultando TikTok…</span> : values.length ? <span className="relative mt-2 block"><select value={selected} onChange={(event) => onChange(event.target.value)} className="rocket-input appearance-none text-sm font-bold"><option value="">Selecione</option>{values.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.id}</option>)}</select><ChevronDown className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500" size={15} /></span> : <span className="mt-2 block normal-case text-xs font-medium text-zinc-500">{empty}</span>}</label>; }

function CatalogScreen({ bc, bcs, catalogs, selectedId, mode, loading, onBc, onRefresh, onSelect, onMode }: { bc: Choice | null; bcs: Choice[]; catalogs: Choice[]; selectedId: string; mode: CatalogMode; loading: boolean; onBc: (id: string) => void; onRefresh: () => void; onSelect: (id: string) => void; onMode: (mode: CatalogMode) => void }) { return <div className="pt-5"><div className="flex items-center justify-between"><p className="text-sm text-zinc-400">Selecione um catálogo por BC. Cada conta usará o catálogo do seu Business Center.</p><button type="button" onClick={onRefresh} className="text-xs font-bold text-sky-300"><RefreshCw className={`mr-1 inline ${loading ? "animate-spin" : ""}`} size={14} />Atualizar</button></div><div className="mt-5 rounded-xl border border-[#d8b56b]/35 bg-[#17150e]/80 p-6"><div className="flex items-center gap-2 text-sm font-black text-zinc-100"><span className="h-2.5 w-2.5 rounded-full bg-[#d8b56b]" />{bc?.name ?? "Selecione um Business Center"}<span className="ml-2 rounded bg-zinc-800 px-2 py-1 text-[10px] text-zinc-400">{catalogs.length} catálogo(s)</span></div><div className="mt-5 flex flex-wrap gap-3">{bcs.map((item) => <button key={item.id} type="button" onClick={() => onBc(item.id)} className={`rounded-xl border px-5 py-4 text-left transition ${item.id === bc?.id ? "border-[#d8b56b] bg-[#28230f]" : "border-white/[.09] bg-[#101417] hover:border-white/[.24]"}`}><p className="font-black text-zinc-100">{item.name}</p><p className="mt-1 text-xs text-zinc-500">ID: {item.id}</p></button>)}</div></div><div className="mt-5 grid gap-4 md:grid-cols-2"><SelectMode icon={<Layers3 size={28} />} title="Selecionar Sets" text="Segmente grupos específicos do catálogo." active={mode === "SETS"} onClick={() => onMode("SETS")} /><SelectMode icon={<Database size={28} />} title="Todos os Produtos" text="Promova todos os produtos do catálogo." active={mode === "ALL"} onClick={() => onMode("ALL")} /></div>{mode === "SETS" && <div className="mt-3 rounded-lg border border-sky-300/20 bg-sky-300/[.05] px-4 py-3 text-xs text-sky-100">A seleção de Product Sets será habilitada quando a API retornar os sets deste catálogo.</div>}<div className="mt-5 grid gap-3 md:grid-cols-2">{loading ? <div className="py-10 text-center text-sm text-zinc-500"><Loader2 className="mx-auto animate-spin text-[#d8b56b]" />Carregando catálogos…</div> : catalogs.map((item) => <button key={item.id} type="button" onClick={() => onSelect(item.id)} className={`catalog-card text-left ${item.id === selectedId ? "catalog-selected" : ""}`}><span className="grid h-9 w-9 place-items-center rounded-lg bg-white/[.06] text-[#d8b56b]"><Database size={17} /></span><p className="mt-4 font-black">{item.name}</p><p className="mt-1 text-xs text-zinc-500">ID: {item.id} · {item.currency || "Moeda da conta"}</p></button>)}</div></div>; }
function SelectMode({ icon, title, text, active = false, onClick }: { icon: React.ReactNode; title: string; text: string; active?: boolean; onClick: () => void }) { return <button type="button" onClick={onClick} aria-pressed={active} className={`flex min-h-[155px] flex-col justify-between rounded-xl border p-6 text-left transition ${active ? "border-[#d8b56b] bg-[#251f0d]" : "border-white/[.07] bg-[#101417] hover:border-white/[.2]"}`}><span className={active ? "text-[#e3c985]" : "text-zinc-400"}>{icon}</span><div><p className="text-xl font-black">{title}</p><p className="mt-2 text-sm text-zinc-400">{text}</p></div></button>; }

function CreativeScreen({ value, pullCatalogText, cta, addon, onChange, onPullCatalogText, onCta, onAddon }: { value: string; pullCatalogText: boolean; cta: string; addon: string; onChange: (v: string) => void; onPullCatalogText: (value: boolean) => void; onCta: (v: string) => void; onAddon: (v: string) => void }) { const calls = [["SHOP_NOW", "Compre Agora"], ["LEARN_MORE", "Saiba Mais"], ["SIGN_UP", "Cadastre-se"], ["CONTACT_US", "Contato"], ["DOWNLOAD", "Download"], ["WATCH_NOW", "Ver Agora"], ["RESERVE_NOW", "Reservar"], ["APPLY_NOW", "Aplicar"]]; const addOns = [["NONE", "Nenhum", X], ["DISPLAY", "Display card", Layers3], ["COUNTDOWN", "Countdown", Timer], ["GIFT", "Gift code", Gift]] as const; return <div className="mx-auto max-w-[565px] pt-4"><div className="rocket-section"><div className="flex items-center justify-between"><p className="section-label">Texto do anúncio</p><button type="button" onClick={() => onPullCatalogText(!pullCatalogText)} aria-pressed={pullCatalogText} className="flex items-center gap-2 text-xs text-zinc-400">Puxar do catálogo <span className={`relative h-5 w-9 rounded-full p-0.5 transition ${pullCatalogText ? "bg-sky-400" : "bg-zinc-600"}`}><span className={`block h-4 w-4 rounded-full bg-white transition ${pullCatalogText ? "translate-x-4" : ""}`} /></span></button></div><textarea value={value} onChange={(event) => onChange(event.target.value)} disabled={pullCatalogText} placeholder={pullCatalogText ? "O texto será obtido dinamicamente do catálogo." : "Digite aqui o texto do anúncio"} className="rocket-input mt-3 min-h-[84px] resize-y disabled:cursor-not-allowed disabled:opacity-55" /></div><div className="rocket-section mt-3"><p className="section-label">Call to action</p><div className="mt-3 flex flex-wrap gap-2">{calls.map(([key, label]) => <button type="button" key={key} onClick={() => onCta(key)} className={`cta-chip ${cta === key ? "cta-selected" : ""}`}>{label}</button>)}</div></div><div className="rocket-section mt-3"><p className="section-label">Complemento interativo</p><div className="mt-3 grid grid-cols-4 gap-3">{addOns.map(([key, label, Icon]) => <button type="button" key={key} onClick={() => onAddon(key)} className={`addon-card ${addon === key ? "addon-selected" : ""}`}><Icon size={27} /><span>{label}</span></button>)}</div></div></div>; }

function StructureScreen({ campaigns, groups, ads, setCampaigns, setGroups, setAds, inputCurrency, setInputCurrency, amount, setAmount, rate, setRate, accountCurrency, budget, counts, country, setCountry, language, setLanguage, campaignName, setCampaignName, aigc, onAigc, cpa, onCpa, clickWindow, onClickWindow, viewWindow, onViewWindow, counting, onCounting, ages, onAges, operatingSystem, onOperatingSystem, showRegions, onShowRegions, regions, onRegions }: { campaigns: string; groups: string; ads: string; setCampaigns: (v: string) => void; setGroups: (v: string) => void; setAds: (v: string) => void; inputCurrency: string; setInputCurrency: (v: string) => void; amount: string; setAmount: (v: string) => void; rate: string; setRate: (v: string) => void; accountCurrency: string; budget: number; counts: { campaigns: number; groups: number; ads: number }; country: string; setCountry: (v: string) => void; language: string; setLanguage: (v: string) => void; campaignName: string; setCampaignName: (v: string) => void; aigc: boolean; onAigc: (value: boolean) => void; cpa: boolean; onCpa: (value: boolean) => void; clickWindow: string; onClickWindow: (value: string) => void; viewWindow: string; onViewWindow: (value: string) => void; counting: string; onCounting: (value: string) => void; ages: string[]; onAges: (value: string[]) => void; operatingSystem: OperatingSystem; onOperatingSystem: (value: OperatingSystem) => void; showRegions: boolean; onShowRegions: () => void; regions: string[]; onRegions: (value: string[]) => void }) {
  const allAges = ["13–17", "18–24", "25–34", "35–44", "45–54", "55+"];
  const regionOptions: Record<string, string[]> = { MX: ["CDMX", "Jalisco", "Nuevo León", "Estado de México"], BR: ["São Paulo", "Rio de Janeiro", "Minas Gerais", "Paraná"], US: ["California", "Florida", "Texas", "New York"], CL: ["Santiago", "Valparaíso", "Biobío", "Maule"] };
  const toggleAge = (age: string) => onAges(ages.includes(age) ? ages.filter((item) => item !== age) : [...ages, age]);
  const toggleRegion = (region: string) => onRegions(regions.includes(region) ? regions.filter((item) => item !== region) : [...regions, region]);
  return <div className="mx-auto max-w-[1210px] pt-5"><div className="structure-grid"><MetricInput label="Campanhas" value={campaigns} onChange={setCampaigns} /><MetricInput label="Grupos" value={groups} onChange={setGroups} /><MetricInput label="Anúncios" value={ads} onChange={setAds} /><label className="structure-metric"><span>Orçamento ({inputCurrency})</span><div className="flex items-center gap-2"><input value={amount} onChange={(event) => setAmount(event.target.value)} className="w-full bg-transparent text-2xl font-black outline-none" /><select value={inputCurrency} onChange={(event) => setInputCurrency(event.target.value)} className="bg-transparent text-sm font-black outline-none">{currencies.map((item) => <option key={item}>{item}</option>)}</select></div></label></div><div className="rocket-section mt-5"><div className="flex items-center justify-between gap-4"><p className="section-label">Conteúdo gerado por IA (AIGC)</p><Toggle value={aigc} onChange={onAigc} /></div><p className="mt-3 text-xs text-zinc-500">Ative somente quando o criativo for realmente gerado por IA.</p></div><div className="rocket-section mt-4"><div className="flex items-center justify-between gap-4"><p className="section-label">Lance (CPA)</p><Toggle value={cpa} onChange={onCpa} /></div><p className="mt-3 text-xs text-zinc-500">Base no custo por aquisição desejado.</p></div><div className="rocket-section mt-4"><p className="section-label">Janela de atribuição</p><div className="mt-4 grid gap-4 md:grid-cols-3"><DarkSelect label="Click" value={clickWindow} values={["7-day click", "1-day click"]} onChange={onClickWindow} /><DarkSelect label="View" value={viewWindow} values={["1-day view", "None"]} onChange={onViewWindow} /><DarkSelect label="Contagem" value={counting} values={["Every", "Once"]} onChange={onCounting} /></div></div><div className="mt-4 grid gap-4 md:grid-cols-[1.2fr_.8fr]"><div className="rocket-section"><div className="flex items-center justify-between"><p className="section-label">Faixas etárias</p><button type="button" onClick={() => onAges(allAges)} className="small-yellow">Todas</button></div><div className="mt-4 flex flex-wrap gap-2">{allAges.map((item) => <button type="button" key={item} onClick={() => toggleAge(item)} aria-pressed={ages.includes(item)} className={`age-chip ${ages.includes(item) ? "age-selected" : ""}`}>{item}</button>)}</div><p className="mt-3 text-xs text-zinc-500">{ages.length} faixa(s) selecionada(s)</p></div><div className="rocket-section"><p className="section-label">Sistema operacional</p><div className="mt-4 grid gap-2">{[["ANDROID", "Android"], ["IOS", "iOS"], ["ALL", "Android + iOS"]].map(([value, label]) => <button type="button" key={value} onClick={() => onOperatingSystem(value as OperatingSystem)} aria-pressed={operatingSystem === value} className={`os-card ${operatingSystem === value ? "os-selected" : ""}`}>{label}</button>)}</div></div></div><div className="mt-4 grid gap-4 md:grid-cols-2"><DarkSelect label="País (location)" value={country} values={["MX", "BR", "US", "CL"]} onChange={(value) => { setCountry(value); onRegions([]); }} /><DarkSelect label="Idioma" value={language} values={["es", "pt", "en"]} onChange={setLanguage} /></div><div className="rocket-section mt-4"><div className="flex items-center justify-between gap-4"><p className="section-label">Estados / regiões (opcional)</p><button type="button" onClick={onShowRegions} className="rocket-dark-button">{showRegions ? "Ocultar regiões" : `Carregar estados de ${country === "MX" ? "México" : country}`}</button></div>{showRegions && <div className="mt-4 flex flex-wrap gap-2">{(regionOptions[country] ?? []).map((region) => <button type="button" key={region} onClick={() => toggleRegion(region)} aria-pressed={regions.includes(region)} className={`age-chip ${regions.includes(region) ? "age-selected" : ""}`}>{region}</button>)}</div>}<p className="mt-3 text-xs text-zinc-500">{regions.length ? `${regions.length} região(ões) selecionada(s).` : "Vazio = país inteiro. Estados selecionados substituem o país no targeting."}</p></div><div className="rocket-section mt-4"><p className="section-label">Campaign naming <span className="ml-2 rounded bg-[#3a3319] px-2 py-1 text-[9px] text-[#e3c985]">nomenclatura</span></p><div className="mt-5 grid gap-5 md:grid-cols-[1.5fr_.65fr]"><label className="text-xs font-bold text-zinc-400">Nome da campanha<input value={campaignName} onChange={(event) => setCampaignName(event.target.value)} placeholder="Ex.: P268MXN-TEST" className="rocket-input mt-2 font-black text-white" /></label><div className="rounded-xl bg-[#101417] p-4 text-center"><p className="text-[10px] font-black uppercase tracking-[.1em] text-zinc-500">Prévia do nome</p><p className="mt-3 rounded-lg border border-[#806a2b] bg-[#29230e] px-4 py-3 text-lg font-black text-[#e3c985]">{campaignName ? `${campaignName} 01.` : "—"}</p></div></div></div><div className="mt-4 rounded-xl border border-[#d8b56b]/25 bg-[#d8b56b]/[.06] p-5"><p className="section-label text-[#e3c985]">Impacto do orçamento</p><p className="mt-2 text-2xl font-black">{money(budget, accountCurrency)} <span className="text-sm font-bold text-zinc-400">por grupo · {counts.groups} grupos · teto diário {money(budget * counts.groups, accountCurrency)}</span></p>{inputCurrency !== accountCurrency && <label className="mt-4 block text-xs text-zinc-400">Cotação: 1 {inputCurrency} em {accountCurrency}<input value={rate} onChange={(event) => setRate(event.target.value)} className="rocket-input mt-2 max-w-xs" /></label>}</div></div>;
}
function MetricInput({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) { return <label className="structure-metric"><span>{label}</span><input type="number" min="1" value={value} onChange={(event) => onChange(event.target.value)} /></label>; }
function DarkSelect({ label, value, values, onChange }: { label: string; value: string; values: string[]; onChange: (v: string) => void }) { return <label className="rocket-section block"><span className="section-label">{label}</span><span className="relative mt-4 block"><select value={value} onChange={(event) => onChange(event.target.value)} className="rocket-input appearance-none font-black">{values.map((item) => <option key={item} value={item}>{item}</option>)}</select><ChevronDown className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500" size={16} /></span></label>; }
function Toggle({ value, onChange }: { value: boolean; onChange: (value: boolean) => void }) { return <button type="button" onClick={() => onChange(!value)} aria-pressed={value} className="flex overflow-hidden rounded-md border border-white/[.08] bg-[#0d1013] text-xs font-black"><span className={`px-5 py-3 ${!value ? "bg-zinc-700 text-zinc-200" : "text-zinc-500"}`}>Off</span><span className={`px-5 py-3 ${value ? "bg-sky-400 text-slate-950" : "text-zinc-500"}`}>On</span></button>; }

function ProxyScreen({ proxy, address, onChange, onAddress }: { proxy: string; address: string; onChange: (value: string) => void; onAddress: (value: string) => void }) { return <div className="mx-auto max-w-[700px] pt-7"><div className="rocket-card p-7"><div className="flex items-center gap-4"><span className="grid h-14 w-14 place-items-center rounded-xl bg-[#142231] text-sky-300"><Orbit size={27} /></span><div><p className="text-xl font-black">Canal de saída</p><p className="mt-1 text-sm text-zinc-400">A rota selecionada acompanha a configuração do lançamento.</p></div></div><div className="mt-7 grid gap-3"><button type="button" onClick={() => onChange("DIRECT")} aria-pressed={proxy === "DIRECT"} className={`proxy-card ${proxy === "DIRECT" ? "proxy-selected" : ""}`}><span><b>Rota direta</b><small>Usar a conexão padrão da operação.</small></span>{proxy === "DIRECT" && <CircleCheck />}</button><button type="button" onClick={() => onChange("DEDICATED")} aria-pressed={proxy === "DEDICATED"} className={`proxy-card ${proxy === "DEDICATED" ? "proxy-selected" : ""}`}><span><b>Proxy dedicado</b><small>Definir uma rota específica antes do lançamento.</small></span>{proxy === "DEDICATED" && <CircleCheck />}</button></div>{proxy === "DEDICATED" && <label className="mt-5 block text-xs font-bold text-zinc-400">URL do proxy<input value={address} onChange={(event) => onAddress(event.target.value)} placeholder="http://host:porta ou socks5://host:porta" className="rocket-input mt-2" /></label>}</div></div>; }
function LaunchScreen({ ready, name, bc, advertiser, catalog, pixel, identity, counts, budget, currency, onOpen }: { ready: boolean; name: string; bc: Choice | null; advertiser: Choice | null; catalog: Choice | null; pixel: Choice | null; identity: Choice | null; counts: { campaigns: number; groups: number; ads: number }; budget: number; currency: string; onOpen: () => void }) { const rows = [["Business Center", bc], ["Conta", advertiser], ["Catálogo", catalog], ["Pixel", pixel], ["Identity", identity]] as const; return <div className="mx-auto max-w-[820px] pt-6"><div className="rocket-card overflow-hidden"><div className="border-b border-white/[.08] px-6 py-5"><p className="section-label">Resumo de lançamento</p><h2 className="thor-title thor-title--asgard mt-2 text-3xl leading-tight">{name || "Operação pendente"}</h2></div><div className="p-6"><div className="divide-y divide-white/[.07]">{rows.map(([label, item]) => <div key={label} className="flex items-center justify-between gap-4 py-3 text-sm"><span className="text-zinc-500">{label}</span><span className={`flex min-w-0 items-center gap-2 text-right font-bold ${item ? "text-emerald-300" : "text-amber-300"}`}>{item ? <CircleCheck size={15} /> : <CircleAlert size={15} />}<span className="truncate">{item?.name ?? "Pendente"}</span></span></div>)}</div><div className="mt-5 rounded-lg border border-[#d8b56b]/35 bg-[#2b250e] p-4"><p className="text-xs text-[#f6df73]">{counts.campaigns} campanha(s) · {counts.groups} grupo(s) · {counts.ads} anúncio(s)</p><p className="mt-2 text-xl font-black">Teto diário: {money(budget * counts.groups, currency)}</p></div><button type="button" disabled={!ready} onClick={onOpen} className="rocket-launch-button mt-6 disabled:opacity-40"><CloudLightning size={19} />Preparar console de lançamento</button></div></div></div>; }
function FooterNav({ step, onBack, onNext, disabled }: { step: number; onBack: () => void; onNext: () => void; disabled: boolean }) { return <footer className="mt-7 flex items-center justify-between"><button type="button" onClick={onBack} className="footer-abort"><ArrowLeft size={16} />{step === 0 ? "Abortar missão" : "Anterior"}</button><button type="button" onClick={onNext} disabled={disabled} className="footer-next disabled:cursor-not-allowed disabled:opacity-40">{step === 6 ? "Preparar lançamento" : "Próxima fase"}<ArrowRight size={17} /></button></footer>; }
function LaunchConsole({ name, counts, budget, currency, ready, onClose }: { name: string; counts: { campaigns: number; groups: number; ads: number }; budget: number; currency: string; ready: boolean; onClose: () => void }) { const logs = [["!", `Conta usa ${currency}; orçamento calculado em ${currency}: ${money(budget, currency)} por grupo.`, "warning"], ["!", `Teto diário estimado: ${money(budget * counts.groups, currency)}.`, "warning"], ["▶", `Campanha: ${name || "sem nome"}`, "info"], ["⚡", `Estrutura: ${counts.campaigns} campanha(s) | ${counts.groups} grupo(s) | ${counts.ads} anúncio(s)`, "info"], ["✓", "Pré-flight concluído. Nenhuma campanha foi criada nesta tela.", ready ? "success" : "error"]] as const; return <div className="fixed inset-0 z-50 grid place-items-center bg-black/80 p-4 backdrop-blur-sm"><div role="dialog" aria-modal="true" className="console-modal"><div className="flex items-center justify-between border-b border-white/[.08] px-6 py-5"><div className="flex items-center gap-3"><span className="console-orb" /><h2 className="text-xl font-black">Preparando campanhas...</h2></div><div className="flex gap-2"><span className="rounded bg-[#4b4116] px-2 py-1 text-[10px] font-black text-[#ffd31a]">2 avisos</span><button type="button" onClick={onClose} className="rounded border border-red-400/40 px-3 py-1 text-[10px] font-black text-red-300">PARAR</button></div></div><div className="p-6"><div className="flex items-center justify-between border-b border-white/[.06] pb-3 text-xs"><div className="flex gap-5 text-zinc-400"><b className="rounded bg-zinc-700 px-3 py-2 text-zinc-100">Todos (5)</b><span>Erros (0)</span><span>Avisos (2)</span><span>Sucesso (1)</span></div><span className="text-sky-300">Copiar · Exportar</span></div><label className="relative mt-4 block"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-600" size={14} /><input className="rocket-input h-9 pl-9 text-xs" placeholder="Buscar nos logs..." /></label><div className="mt-5 h-[245px] space-y-3 overflow-y-auto font-mono text-xs leading-5">{logs.map(([mark, text, tone], index) => <p key={index} className={tone === "success" ? "text-emerald-300" : tone === "warning" ? "text-[#ffd31a]" : tone === "error" ? "text-red-300" : "text-sky-300"}><span className="mr-3 opacity-60">[{new Date().toLocaleTimeString("pt-BR", { hour12: false })}]</span><b className="mr-2">{mark}</b>{text}</p>)}</div><div className="mt-5 border-t border-white/[.08] pt-4"><p className="font-black">Resumo: <span className="text-emerald-300">1 sucesso</span> · <span className="text-[#ffd31a]">2 avisos</span></p><p className="mt-4 text-[10px] font-black uppercase tracking-[.13em] text-zinc-500">A criação real será habilitada após integrar o endpoint de publicação do TikTok.</p></div></div><div className="flex justify-center border-t border-white/[.08] px-6 py-5"><button type="button" onClick={onClose} className="console-close">Fechar</button></div></div></div>; }
